<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {Stage45Api,FundsOrder,Page} from '../../../business-common/stage45/types'
import {money,date,label} from '../../../business-common/stage45/presentation'
import BaseCard from '../BaseCard.vue'
import AppButton from '../AppButton.vue'
const props=defineProps<{api:Stage45Api;refreshKey?:number}>(),emit=defineEmits<{open:[id:string]}>()
const data=ref<Page<FundsOrder>|null>(null),page=ref(1),q=ref(''),fundState=ref(''),fromDay=ref(''),toDay=ref(''),loading=ref(false),error=ref('');let ticket=0
async function load(){if(fromDay.value&&toDay.value&&fromDay.value>toDay.value){data.value=null;error.value='下单起日不能晚于止日。';return}const run=++ticket,owner=props.api.owner();loading.value=true;error.value='';try{const value=await props.api.read<Page<FundsOrder>>('/funds',{pageNumber:page.value,pageSize:20,q:q.value,fundState:fundState.value,...(fromDay.value?{from:new Date(fromDay.value+'T00:00:00+08:00').toISOString()}:{}),...(toDay.value?{to:new Date(Date.parse(toDay.value+'T00:00:00+08:00')+86400000).toISOString()}:{} )});if(run===ticket&&owner===props.api.owner())data.value=value}catch(e){if(run===ticket){data.value=null;error.value=e instanceof Error?e.message:'资金读取失败。'}}finally{if(run===ticket)loading.value=false}}
const filters=[{value:'',label:'全部'},{value:'PENDING',label:'资金处理中'},{value:'EXCEPTION',label:'异常待核实'},{value:'REFUNDED',label:'已有退款'},{value:'FINISHED',label:'已完结／解冻'}]
function filter(value:string){fundState.value=value;page.value=1;load()}
function search(reset=false){if(reset){q.value='';fundState.value='';fromDay.value='';toDay.value=''}page.value=1;load()}
watch(()=>props.api.owner(),()=>{ticket++;data.value=null;q.value='';fundState.value='';fromDay.value='';toDay.value='';page.value=1;load()},{immediate:true});watch(()=>props.refreshKey,load);onBeforeUnmount(()=>{ticket++;data.value=null})
</script>
<template><view class="s45"><view class="hero"><text class="hero-title">本店订单资金</text><text>按原订单核对实付、已退和资金进度</text></view><view class="search"><input v-model="q" maxlength="80" placeholder="订单号或店铺名称" @confirm="search()"/><AppButton class="s45-action" size="compact" @click="search()">查询</AppButton></view><view class="row"><picker mode="date" :value="fromDay" @change="fromDay=$event.detail.value"><text class="picker">下单日起：{{fromDay||'请选择'}}</text></picker><picker mode="date" :value="toDay" @change="toDay=$event.detail.value"><text class="picker">下单日止：{{toDay||'请选择'}}</text></picker></view><text class="muted">日期按北京时间，止日包含全天。</text><scroll-view scroll-x><view class="tabs"><view v-for="item in filters" :key="item.value" class="tab" :class="{selected:fundState===item.value}" @click="filter(item.value)">{{item.label}}</view></view></scroll-view><AppButton class="s45-action" variant="secondary" size="compact" @click="search(true)">重置</AppButton><BaseCard v-if="error"><text class="error" role="alert">{{error}}</text><AppButton class="s45-action" @click="load">重新读取</AppButton></BaseCard><text v-if="loading" class="state">正在读取本店资金…</text><BaseCard v-for="row in data?.records" :key="row.orderId"><text class="strong">{{row.storeName}}</text><text class="muted">订单 {{row.orderSn}} · {{label(row.mode)}}</text><view class="row"><text>可信实付</text><text>¥{{money(row.paidCent)}}</text></view><view class="row"><text>商品／费用已退</text><text>{{row.goodsRefundCent==null?'待核实':'¥'+money(row.goodsRefundCent)+' / ¥'+money(row.feeRefundCent)}}</text></view><view class="row"><text>本订单实际净额</text><text class="price">{{row.netCent==null?'待核实':'¥'+money(row.netCent)}}</text></view><text class="muted">{{row.fundProgress?label(row.fundProgress):row.blockReason?'原付款或快照待核实':row.exceptionCount?'有资金异常待处理':row.pendingObligationCent?'有未完成退款义务':row.finished?'已核完结／解冻':'资金进度以详情为准'}}</text><text class="muted">{{date(row.createdAt)}}</text><AppButton class="s45-action" variant="secondary" @click="emit('open',row.orderId)">查看本订单资金</AppButton></BaseCard><BaseCard v-if="data&&!data.records.length&&!loading"><text class="state">{{q||fundState||fromDay||toDay?'没有符合筛选的订单。':'当前没有可查看的订单资金记录。'}}</text></BaseCard><view v-if="data" class="buttons"><AppButton class="s45-action" variant="secondary" :disabled="loading||page<=1" @click="page--;load()">上一页</AppButton><text>{{page}} 页 · {{data.total}} 条</text><AppButton class="s45-action" variant="secondary" :disabled="loading||page*data.pageSize>=data.total" @click="page++;load()">下一页</AppButton></view></view></template>
<style scoped lang="scss">@import './stage45.scss';</style>
